prompt --application/shared_components/logic/application_processes/get_document
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(18799727877348194921)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_DOCUMENT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_blob       BLOB;',
'    v_mime       VARCHAR2 (255);',
'    v_filename   VARCHAR2 (255);',
'BEGIN',
'    -- Retrieve the file details based on DOCUMENT_ID',
'    SELECT DOCUMENT_FILE,',
'           CASE',
'               WHEN ATTACH_FILENAME LIKE ''%.pdf''',
'               THEN',
'                   ''application/pdf''                          -- PDF MIME type',
'               WHEN    ATTACH_FILENAME LIKE ''%.xls''',
'                    OR ATTACH_FILENAME LIKE ''%.xlsx''',
'               THEN',
'                   ''application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'' -- Excel MIME type',
'               WHEN ATTACH_FILENAME LIKE ''%.docx''',
'               THEN',
'                   ''application/vnd.openxmlformats-officedocument.wordprocessingml.document'' -- Word MIME type',
'               WHEN ATTACH_FILENAME LIKE ''%.csv''',
'               THEN',
'                   ''text/csv''                                 -- CSV MIME type',
'               WHEN    ATTACH_FILENAME LIKE ''%.jpg''',
'                    OR ATTACH_FILENAME LIKE ''%.jpeg''',
'                    OR ATTACH_FILENAME LIKE ''%.png''',
'               THEN',
'                   ''image/jpeg''                             -- Image MIME type',
'               ELSE',
'                   ''application/octet-stream'' -- Default MIME type for unknown file types',
'           END    AS v_mime,',
'           ATTACH_FILENAME                               -- Fetch the filename',
'      INTO v_blob, v_mime, v_filename',
'      FROM DOCUMENTS_T',
'     WHERE DOCUMENT_ID = :P5_DOCUMENT_ID; -- Fetch the record for the provided document ID',
'',
'    -- Set the response headers to indicate the file type and inline display',
'    OWA_UTIL.MIME_HEADER (v_mime, FALSE); -- Set the MIME type in the HTTP response header',
'',
'    -- Set the Content-Disposition header to attempt opening the file inline (in the browser)',
'    HTP.P (''Content-Disposition: inline; filename="'' || v_filename || ''"'');',
'',
'    -- Prevent browser caching to always fetch the latest file',
'    HTP.P (''Cache-Control: no-store'');',
'    HTP.P (''Pragma: no-cache'');',
'',
'    -- Close the HTTP headers before sending the file data',
'    OWA_UTIL.HTTP_HEADER_CLOSE;',
'',
'    -- Send the document to the browser so the user can view it',
'    WPG_DOCLOAD.DOWNLOAD_FILE (v_blob);',
'',
'    -- Stop further APEX processing to prevent any additional output',
'    APEX_APPLICATION.STOP_APEX_ENGINE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>15611128978071
);
end;
