,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function () {',
'',
'    function placeSearch() {',
'        var $nav = $(".t-Body-nav");   // side nav container',
'        if (!$nav.length) return;',
'',
'        // Avoid duplicate',
'        if ($nav.find("#navSearch").length) return;',
'',
'        // Create input container',
'        var $searchContainer = $(''<div id="sideNavSearch" class="sidenav-search" style="padding:5px;"></div>'');',
'        var $input = $(''<input type="text" id="navSearch" placeholder="Search menu..." class="apex-item-text" style="width:100%; padding:6px;">'');',
'        $searchContainer.append($input);',
'        $nav.prepend($searchContainer);',
'    }',
'',
'    // Initial placement',
'    placeSearch();',
'',
'    // Re-attach after sidebar refresh / resize',
'    $(window).on("resize", placeSearch);',
'',
'    // Use delegated event in case input is dynamically re-added',
'    $(document).on("keyup", "#navSearch", function () {',
'        var value = $(this).val().toLowerCase();',
'',
'        $("#t_TreeNav li").each(function () {',
'            var $li = $(this);',
'            if ($li.find("#navSearch").length) return; // skip search input itself',
'',
'            var text = $li.children("a").text().toLowerCase();',
'            var match = text.indexOf(value) > -1;',
'',
'            $li.toggle(match);',
'',
'            if (match) {',
'                $li.parents("li").show();',
'            }',
'        });',
'    });',
'',
'})();',
''))
);
