,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function () {',
'',
'    function placeSearch() {',
'        var $nav = $("#t_Body_nav"); ',
'        if (!$nav.length) return;',
'        if ($nav.find("#navSearch").length) return;',
'',
'        // Create search input',
'        var $searchContainer = $(''<div id="sideNavSearch" style="padding:5px;"></div>'');',
'        var $input = $(''<input type="text" id="navSearch" placeholder="Search menu..." style="width:100%; padding:6px;">'');',
'        $searchContainer.append($input);',
'        $nav.prepend($searchContainer);',
'',
'        // Show sidebar after adding search',
'        $nav.css("visibility", "visible");',
'    }',
'',
'    placeSearch();',
'    $(window).on("resize", placeSearch);',
'',
'    // Recursive function to check child matches',
'    function hasMatchingChild($li, searchValue) {',
'        var match = false;',
'        $li.find("> ul > li.a-TreeView-node").each(function () {',
'            var $child = $(this);',
'            var $label = $child.find("> .a-TreeView-content > a.a-TreeView-label");',
'            var text = $label.text().toLowerCase();',
'',
'            // Reset previous highlights',
'            $label.html($label.text());',
'',
'            if (text.indexOf(searchValue) > -1 || hasMatchingChild($child, searchValue)) {',
'                match = true;',
'                $child.show();',
'                $child.children("ul").show();',
'                highlightText($label, searchValue);',
'            } else {',
'                $child.hide();',
'            }',
'        });',
'        return match;',
'    }',
'',
'    // Function to highlight matched text',
'    function highlightText($element, searchValue) {',
'        if (!searchValue) return;',
'        var text = $element.text();',
'        var regex = new RegExp("(" + searchValue.replace(/[-\/\\^$*+?.()|[\]{}]/g, ''\\$&'') + ")", "gi");',
'        $element.html(text.replace(regex, ''<span class="sidebar-highlight">$1</span>''));',
'    }',
'',
'    // Filter sidebar on keyup',
'    $(document).on("keyup", "#navSearch", function () {',
'        var value = $(this).val().toLowerCase();',
'',
'        $("#t_TreeNav li.a-TreeView-node").each(function () {',
'            var $li = $(this);',
'            var $label = $li.find("> .a-TreeView-content > a.a-TreeView-label");',
'            var text = $label.text().toLowerCase();',
'',
'            // Reset previous highlights',
'            $label.html($label.text());',
'',
'            // Show all if search box is empty',
'            if (value === "") {',
'                $li.show();',
'                $li.children("ul").show();',
'                return;',
'            }',
'',
'            var selfMatch = text.indexOf(value) > -1;',
'            var childMatch = hasMatchingChild($li, value);',
'',
'            if (selfMatch || childMatch) {',
'                $li.show();',
'                $li.children("ul").show();',
'                if (selfMatch) highlightText($label, value);',
'            } else {',
'                $li.hide();',
'            }',
'        });',
'    });',
'',
'})();',
''))
);
