'(function () {',
'',
'    /* -------------------------',
'       Create search box',
'    --------------------------*/',
'    function placeSearch() {',
'        var $nav = $("#t_Body_nav");',
'        if (!$nav.length) return;',
'        if ($nav.find("#navSearch").length) return;',
'',
'        var $searchContainer = $(''<div id="sideNavSearch" style="padding:6px;"></div>'');',
'        var $input = $(''<input type="text" id="navSearch" placeholder="Search menu..." style="width:100%;padding:6px;">'');',
'',
'        $searchContainer.append($input);',
'        $nav.prepend($searchContainer);',
'',
'        $("#t_Body_nav").css("visibility", "visible");',
'    }',
'',
'    placeSearch();',
'    $(window).on("resize", placeSearch);',
'',
'    /* -------------------------',
'       Highlight text',
'    --------------------------*/',
'    function highlightText($el, value) {',
'        if (!value) return;',
'',
'        var text = $el.text();',
'        var regex = new RegExp("(" +',
'            value.replace(/[-\/\\^$*+?.()|[\]{}]/g, "\\$&") +',
'            ")", "gi");',
'',
'        $el.html(text.replace(regex,',
'            ''<span class="sidebar-highlight">$1</span>''',
'        ));',
'    }',
'',
'    /* -------------------------',
'       Recursive child search',
'    --------------------------*/',
'    function hasMatchingChild($li, value) {',
'        var found = false;',
'',
'        $li.children("ul")',
'           .children("li.a-TreeView-node")',
'           .each(function () {',
'',
'            var $child = $(this);',
'            var $label = $child.find("> .a-TreeView-content > a.a-TreeView-label");',
'            var text = $label.text().toLowerCase();',
'',
'            // reset old highlight',
'            $label.html($label.text());',
'',
'            if (text.indexOf(value) > -1 || hasMatchingChild($child, value)) {',
'                found = true;',
'                $child.show();',
'                $child.children("ul").show();',
'',
'                if (text.indexOf(value) > -1) {',
'                    highlightText($label, value);',
'                }',
'            } else {',
'                $child.hide();',
'            }',
'        });',
'',
'        return found;',
'    }',
'',
'    /* -------------------------',
'       Search filter',
'    --------------------------*/',
'    $(document).on("keyup", "#navSearch", function () {',
'',
'        var value = this.value.toLowerCase();',
'',
'        $("#t_TreeNav li.a-TreeView-node").each(function () {',
'',
'            var $li = $(this);',
'            var $label = $li.find("> .a-TreeView-content > a.a-TreeView-label");',
'            var text = $label.text().toLowerCase();',
'',
'            // reset highlight',
'            $label.html($label.text());',
'',
'            if (!value) {',
'                $li.show();',
'                $li.children("ul").show();',
'                return;',
'            }',
'',
'            var selfMatch = text.indexOf(value) > -1;',
'            var childMatch = hasMatchingChild($li, value);',
'',
'            if (selfMatch || childMatch) {',
'                $li.show();',
