'(function () {',
'',
'    const KEY = "apex_menu_history", MAX = 8;',
'',
'    function init() {',
'        let $nav = $("#t_Body_nav");',
'        if (!$nav.length || $("#navSearch").length) return;',
'',
'        $nav.prepend(`',
'            <div id="sideNavSearch">',
'                <input id="navSearch" placeholder="Search menu...">',
'                <button id="navHistoryBtn" type="button" class="t-Button t-Button--noUI"><span class="t-Icon fa fa-history"></span></button>',
'                <div id="navHistoryPopup"></div>',
'            </div>',
'        `).css("visibility","visible");',
'    }',
'',
'    init();',
'',
'    const highlight = ($e,v)=>',
'        v && $e.html($e.text().replace(',
'            new RegExp("(" + v.replace(/[.*+?^${}()|[\]\\]/g,"\\$&") + ")","gi"),',
'            ''<span class="sidebar-highlight">$1</span>''',
'        ));',
'',
'    function childMatch($li,v){',
'        let f=false;',
'        $li.children("ul").children(".a-TreeView-node").each(function(){',
'            let $c=$(this),$l=$c.find("> .a-TreeView-content > a"),',
'                t=$l.text().toLowerCase();',
'            $l.html($l.text());',
'            if(t.includes(v)||childMatch($c,v)){',
'                f=true; $c.show().children("ul").show();',
'                if(t.includes(v)) highlight($l,v);',
'            } else $c.hide();',
'        });',
'        return f;',
'    }',
'',
'    $(document).on("keyup","#navSearch",function(){',
'        let v=this.value.toLowerCase();',
'        $("#t_TreeNav .a-TreeView-node").each(function(){',
'            let $li=$(this),$l=$li.find("> .a-TreeView-content > a"),',
'                t=$l.text().toLowerCase();',
'            $l.html($l.text());',
'            if(!v){$li.show().children("ul").show();return;}',
'            (t.includes(v)||childMatch($li,v))',
'                ? ($li.show().children("ul").show(),t.includes(v)&&highlight($l,v))',
'                : $li.hide();',
'        });',
'    });',
'',
'    $(document).on("click","#t_TreeNav a.a-TreeView-label",function(){',
'        let h=this.href,t=this.textContent.trim();',
'        if(!h||h==="#")return;',
'        let l=JSON.parse(localStorage.getItem(KEY)||"[]").filter(x=>x.h!==h);',
'        l.unshift({t,h});l.length=MAX;',
'        localStorage.setItem(KEY,JSON.stringify(l));',
'    });',
'',
'   function renderPopup() {',
'',
'    let raw = JSON.parse(localStorage.getItem(KEY) || "[]");',
'',
unistr('    // \2705 CLEAN corrupted entries'),
'    let list = raw.filter(x => x && x.h && x.t);',
'',
'    // rewrite clean list back',
'    localStorage.setItem(KEY, JSON.stringify(list));',
'',
'    $("#navHistoryPopup").html(',
'        list.length',
'            ? `<ul>${list.map(x =>',
'                `<li><a href="${x.h}">${x.t}</a></li>`',
'              ).join("")}</ul>`',
'            : `<div class="empty">No recent menu</div>`',
'    );',
'}',
'',
'',
unistr('    /* \D83D\DD12 NO SUBMIT GUARANTEED */'),
'    $(document).on("click","#navHistoryBtn",function(e){',
'        e.preventDefault();   // stop submit',
'        e.stopPropagation();  // stop APEX events',
'        renderPopup();',
'        $("#navHistoryPopup").toggle();',
'        return false;',
'    });',
'',
'    $(document).on("click",function(){',
'        $("#navHistoryPopup").hide();',
'    });',
'',
'})();',
''))
);
end;
