,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Sending Apex Mail With Multi attached'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_mail_id     NUMBER;',
'    l_blob        BLOB;',
'    l_clob        CLOB;',
'    l_body_html   CLOB;',
'BEGIN',
'    l_blob := UTL_RAW.cast_to_raw (''This could be a document or image.'');',
'    l_clob := ''This could be any CLOB information'';',
'',
'    l_body_html :=',
'           ''<html><head></head><body>''',
'        || ''<p>HTML message body.</p>''',
'        || ''</body></html>'';',
'',
'    l_mail_id :=',
'        apex_mail.send (p_to          => :P3_TO_MAIL,',
'                        p_from        => :P3_FROM_MAIL,',
'                        p_body        => :P3_MAIL_BODY,',
'                        p_body_html   => NULL,',
'                        p_subj        => :P3_SUBJECT);',
'',
'    FOR I',
'        IN (WITH',
'                file_ids',
'                AS',
'                    (    SELECT REGEXP_SUBSTR ( :P3_ATTACHED,',
'                                               ''[^:]+'',',
'                                               1,',
'                                               LEVEL)    AS file_name',
'                           FROM DUAL',
'                     CONNECT BY REGEXP_SUBSTR ( :P3_ATTACHED,',
'                                               ''[^:]+'',',
'                                               1,',
'                                               LEVEL)',
'                                    IS NOT NULL)',
'            SELECT aatf.blob_content, aatf.filename, aatf.mime_type',
'              FROM apex_application_temp_files  aatf',
'                   JOIN file_ids f ON f.file_name = aatf.name',
'             WHERE aatf.application_id = :APP_ID)',
'    LOOP',
'        apex_mail.add_attachment (p_mail_id      => l_mail_id,',
'                                  p_attachment   => i.blob_content,',
'                                  p_filename     => i.filename,',
'                                  p_mime_type    => i.mime_type);',
'    END LOOP;',
'',
'    apex_mail.push_queue;',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(27982601741663699436)
,p_process_success_message=>'Email Sent to &P3_TO_MAIL.'
,p_internal_uid=>27982601264375699431
);
