 p_id=>wwv_flow_imp.id(70584082703329665003)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Sending Apex Mail With Zip'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_mail_id          NUMBER;',
'    l_zip_file         BLOB;',
'    l_download_file_name VARCHAR2(64) := ''attachments.zip'';',
'    l_body_html        CLOB;',
'    l_disposition      VARCHAR2(30) := ''attachment'';',
'BEGIN',
'    -- Create an empty ZIP file',
'    DBMS_LOB.createtemporary(l_zip_file, FALSE);',
'',
'    -- Initialize HTML email body',
'    l_body_html := ',
'           ''<html><head></head><body>''',
'        || ''<p>HTML message body with details here.</p>''',
'        || ''</body></html>'';',
'',
'    -- Loop through the files and add them to the ZIP file',
'    FOR i IN (',
'        WITH file_ids AS (',
'            SELECT REGEXP_SUBSTR(:P3_ATTACHED, ''[^:]+'', 1, LEVEL) AS file_name',
'            FROM DUAL',
'            CONNECT BY REGEXP_SUBSTR(:P3_ATTACHED, ''[^:]+'', 1, LEVEL) IS NOT NULL',
'        )',
'        SELECT aatf.blob_content, aatf.filename, aatf.mime_type',
'        FROM apex_application_temp_files aatf',
'        JOIN file_ids f ON f.file_name = aatf.name',
'        WHERE aatf.application_id = :APP_ID',
'    ) LOOP',
'        -- Add each file to the ZIP archive',
'        apex_zip.add_file(',
'            p_zipped_blob  => l_zip_file,',
'            p_file_name    => i.filename,',
'            p_content      => i.blob_content',
'        );',
'    END LOOP;',
'',
'    -- Finalize the ZIP archive (finish and store it in the BLOB)',
'    apex_zip.finish(p_zipped_blob => l_zip_file);',
'',
'    -- Send the email with the attached ZIP file',
'    l_mail_id := apex_mail.send(',
'        p_to         => :P3_TO_MAIL,',
'        p_from       => :P3_FROM_MAIL,',
'        p_subj       => :P3_SUBJECT,',
'        p_body       => :P3_MAIL_BODY,      -- Plain text body',
'        p_body_html  => NULL         -- HTML body',
'    );',
'',
'    -- Attach the ZIP file to the email',
'    apex_mail.add_attachment(',
'        p_mail_id     => l_mail_id,',
'        p_attachment  => l_zip_file,',
'        p_filename    => l_download_file_name,',
'        p_mime_type   => ''application/zip''',
'    );',
'',
'    -- Push the email to the APEX mail queue',
'    apex_mail.push_queue;',
'',
'    -- Commit transaction',
'    COMMIT;',
'',
'    -- Free the temporary BLOB',
'    DBMS_LOB.freetemporary(l_zip_file);',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        -- Free the temporary BLOB in case of error',
'        DBMS_LOB.freetemporary(l_zip_file);',
'        RAISE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(70584082835672665004)
,p_process_success_message=>'Email Sent to &P3_TO_MAIL.'
,p_internal_uid=>70584082703329665003
);
end;
