,p_process_name=>'Process form New'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 1/5/2026 6:32:11 PM (QP5 v5.388) */',
'DECLARE',
'    v_blob        BLOB;',
'    v_filename    VARCHAR2 (255);',
'    v_mime_type   VARCHAR2 (255);',
'BEGIN',
'    -- Fetch the latest uploaded file from APEX_APPLICATION_TEMP_FILES',
'    SELECT blob_content, filename, mime_type',
'      INTO v_blob, v_filename, v_mime_type',
'      FROM APEX_APPLICATION_TEMP_FILES',
'     WHERE name = :P5_DOCUMENT_FILE;',
'',
'    -- Insert into DOCUMENTS_T table',
'    DELETE FROM DOCUMENTS_T;',
'',
'    INSERT INTO DOCUMENTS_T (DOCUMENT_ID,',
'                             DOCUMENT_FILE,',
'                             ATTACH_FILENAME,',
'                             UPLOAD_DATE,',
'                             UPLOADED_BY)',
'         VALUES (DBMS_RANDOM.VALUE (1, 500),',
'                 v_blob,',
'                 v_filename,',
'                 SYSDATE,',
'                 :APP_USER);',
'',
'    COMMIT;                                                -- Save the changes',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Successfully Uploaded.'
,p_internal_uid=>18228451357080916226
);
end;
