prompt --application/pages/page_00006
begin
wwv_flow_imp_page.create_page(
 p_id=>6
,p_name=>'Dynamic Page'
,p_alias=>'DYNAMIC-PAGE'
,p_step_title=>'Dynamic Page'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function updateJsonData() {',
'  var formData = {};',
'',
'  // Loop through all input fields, selects, and textareas within the form',
'  $("#my_dynamic_form").find("input[name], select[name], textarea[name]").each(function() {',
'    var fieldName = $(this).attr("name");',
'    var fieldValue;',
'',
'    // Handle checkbox inputs (value if checked, null if unchecked)',
'    if ($(this).attr("type") === "checkbox") {',
'      fieldValue = this.checked ? $(this).val() || "Y" : null;  // Default value for checked checkbox is "Y"',
'    }',
'    // Handle radio buttons (only include value of selected radio button)',
'    else if ($(this).attr("type") === "radio") {',
'      if (this.checked) {',
'        fieldValue = $(this).val();',
'      } else {',
'        return; // Skip unchecked radio buttons',
'      }',
'    }',
'    // For all other input types (text, select, textarea)',
'    else {',
'      fieldValue = $(this).val();',
'    }',
'',
'    // Only add non-null values to the JSON object',
'    if (fieldName && fieldValue !== undefined && fieldValue !== null) {',
'      formData[fieldName] = fieldValue;',
'    }',
'  });',
'',
'  // Convert the form data into a JSON string',
'  var jsonData = JSON.stringify(formData);',
'',
'  // Set the JSON string to the APEX item (e.g., :P6_JSON_DATA)',
'  $("#P6_JSON_DATA").val(jsonData); // assuming P6_JSON_DATA is the hidden item to store the JSON',
'}',
'',
'// Bind the updateJsonData function to the change, keyup, and click events (delegated)',
'$("#my_dynamic_form").on("change keyup click", "input[name], select[name], textarea[name]", updateJsonData);',
'',
'',
'',
