 p_id=>wwv_flow_imp.id(46983603890784835920)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_DYNAMIC_FORM'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    j                   apex_json.t_values;',
'    l_keys              wwv_flow_t_varchar2;',
'    l_value             VARCHAR2 (4000);',
'    vClob               CLOB := APEX_APPLICATION.g_x01;',
'    l_required_fields   wwv_flow_t_varchar2;',
'    vError              VARCHAR2 (3000);',
'',
'    FUNCTION key_exists (p_key VARCHAR2, p_keys wwv_flow_t_varchar2)',
'        RETURN BOOLEAN',
'    IS',
'    BEGIN',
'        FOR i IN 1 .. p_keys.COUNT',
'        LOOP',
'            IF UPPER (p_keys (i)) = UPPER (p_key)',
'            THEN',
'                RETURN TRUE;',
'            END IF;',
'        END LOOP;',
'',
'        RETURN FALSE;',
'    END;',
'BEGIN',
'    -- Get all required item names for the form',
'    SELECT ITEM_NAME',
'      BULK COLLECT INTO l_required_fields',
'      FROM form_metadata',
'     WHERE     form_id = :P6_FORM_NAME',
'           AND UPPER (VALIDATION_TYPE) LIKE ''%REQUIRED%'';',
'',
'    -- Parse the JSON payload once',
'    apex_json.parse (j, vClob);',
'',
'    -- Get all top-level JSON keys',
'    l_keys := apex_json.get_members (p_values => j, p_path => ''.'');',
'',
'    -- Validate required fields presence and non-empty',
'    FOR i IN 1 .. l_required_fields.COUNT',
'    LOOP',
'        apex_json.parse (vClob);',
'',
'        IF NOT key_exists (l_required_fields (i), l_keys)',
'        THEN',
'            vError :=',
'                   ''Required field "''',
'                || l_required_fields (i)',
'                || ''" is missing.'';',
'            apex_json.open_object;',
'            apex_json.write (''status'', ''error'');',
'            apex_json.write (''message'', vError);',
'            apex_json.close_object;',
'            RETURN;',
'        END IF;',
'',
'        l_value := apex_json.get_varchar2 (l_required_fields (i));',
'',
'        IF l_value IS NULL OR TRIM (l_value) = ''''',
'        THEN',
'            vError :=',
'                   ''Required field "''',
'                || l_required_fields (i)',
'                || ''" cannot be empty.''',
'                || l_value;',
'            apex_json.open_object;',
'            apex_json.write (''status'', ''error'');',
'            apex_json.write (''message'', vError);',
'            apex_json.close_object;',
'            RETURN;',
'        END IF;',
'    END LOOP;',
'',
'    -- Insert all key-value pairs into the log table',
'    FOR i IN 1 .. l_keys.COUNT',
'    LOOP',
'        l_value := apex_json.get_varchar2 (l_keys (i));',
'',
'        INSERT INTO FORM_SUBMISSION_LOG (FORM_NAME,',
'                                         ITEM_NAME,',
'                                         ITEM_VALUE,',
'                                         SUBMIT_DATE)',
'             VALUES (''EMP_FORM'',',
'                     l_keys (i),',
'                     l_value,',
'                     SYSDATE);',
'    END LOOP;',
'',
'    COMMIT;',
'',
'    apex_json.open_object;',
'    apex_json.write (''status'', ''success'');',
'    apex_json.write (''message'', ''Form saved successfully'');',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN',
'        apex_json.open_object;',
'        apex_json.write (''status'', ''error'');',
'        apex_json.write (''message'', SUBSTR (SQLERRM, 1, 3000));',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>46983603890784835920
);
end;
