'    :P7_DISPLAY_ONLY     := apex_json.get_varchar2(''readOnly'');',
'    :P7_START_NEW_ROW    := apex_json.get_varchar2(''startNewRow'');',
'    :P7_MAX_LENGTH       := apex_json.get_varchar2(''maximumvalue'');',
'    :P7_MIN_LENGTH       := apex_json.get_varchar2(''minimumvalue'');',
'    :P7_ITEM_LENGTH      := apex_json.get_varchar2(''itemMaxLength'');',
'    :P7_LABEL_IN_ABOVE   := apex_json.get_varchar2(''labelInAbove'');',
'',
'',
'--raise_application_error (-20001, :P7_DISPLAY_ONLY );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P7_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>48065552945775515729
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(49131292937975143632)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Setup Form'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
':P7_OTHER_ATTRIBUTES := ''{',
'	"readOnly": "''||:P7_DISPLAY_ONLY||''",',
'	"startNewRow": "''||:P7_START_NEW_ROW||''",',
'	"maximumvalue": "''||:P7_MAX_LENGTH||''",',
'	"minimumvalue": "''||:P7_MIN_LENGTH||''",',
'	"itemMaxLength": "''||:P7_ITEM_LENGTH||''",',
'    "labelInAbove" : "''||:P7_LABEL_IN_ABOVE||''"',
'}'';',
'',
'',
'',
'INSERT INTO WKSP_AYUBWP.FORM_METADATA (',
'    FORM_ID, ITEM_NAME, ITEM_LABEL, ITEM_TYPE, VALIDATION_TYPE, VALIDATION_PARAM,',
'    LOV_QUERY, DISPLAY_ORDER, ITEM_CLASS, ITEM_CUSTOM_ATTRIBUTE, OTHER_ATTRIBUTES',
') VALUES (',
'    :P7_FORM_ID, :P7_ITEM_NAME, :P7_ITEM_LABEL, :P7_ITEM_TYPE, :P7_VALIDATION_TYPE, :P7_VALIDATION_PARAM,',
'    :P7_LOV_QUERY,:P7_DISPLAY_ORDER,:P7_ITEM_CLASS,:P7_ITEM_CUSTOM_ATTRIBUTE,:P7_OTHER_ATTRIBUTES',
');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>49131292937975143632
);
