wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(49131294292133143645)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_FORM_METADATA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_other_attributes CLOB;',
'BEGIN',
'  -- Build the JSON string dynamically',
'  v_other_attributes := ''{'' ||',
'    ''"readOnly": "'' || NVL(:P7_DISPLAY_ONLY, ''N'') || ''",'' ||',
'    ''"startNewRow": "'' || NVL(:P7_START_NEW_ROW, ''N'') || ''",'' ||',
'    ''"maximumvalue": "'' || NVL(:P7_MAX_LENGTH, '''') || ''",'' ||',
'    ''"minimumvalue": "'' || NVL(:P7_MIN_LENGTH, '''') || ''",'' ||',
'    ''"labelInAbove": "'' || NVL(:P7_LABEL_IN_ABOVE, ''N'') || ''",'' ||',
'    ''"itemMaxLength": "'' || NVL(:P7_ITEM_LENGTH, '''') || ''"'' ||',
'    ',
'  ''}'';',
'',
'  IF :P7_ID IS NOT NULL THEN',
'    UPDATE WKSP_AYUBWP.FORM_METADATA',
'    SET',
'      FORM_ID = :P7_FORM_ID,',
'      ITEM_NAME = :P7_ITEM_NAME,',
'      ITEM_LABEL = :P7_ITEM_LABEL,',
'      ITEM_TYPE = :P7_ITEM_TYPE,',
'      VALIDATION_TYPE = :P7_VALIDATION_TYPE,',
'      VALIDATION_PARAM = :P7_VALIDATION_PARAM,',
'      LOV_QUERY = :P7_LOV_QUERY,',
'      DISPLAY_ORDER = TO_NUMBER(:P7_DISPLAY_ORDER),',
'      ITEM_CLASS = :P7_ITEM_CLASS,',
'      ITEM_CUSTOM_ATTRIBUTE = :P7_ITEM_CUSTOM_ATTRIBUTE,',
'      OTHER_ATTRIBUTES = v_other_attributes',
'    WHERE ID = :P7_ID;',
'  ELSE',
'    INSERT INTO WKSP_AYUBWP.FORM_METADATA (',
'      FORM_ID,',
'      ITEM_NAME,',
'      ITEM_LABEL,',
'      ITEM_TYPE,',
'      VALIDATION_TYPE,',
'      VALIDATION_PARAM,',
'      LOV_QUERY,',
'      DISPLAY_ORDER,',
'      ITEM_CLASS,',
'      ITEM_CUSTOM_ATTRIBUTE,',
'      OTHER_ATTRIBUTES',
'    ) VALUES (',
'      :P7_FORM_ID,',
'      :P7_ITEM_NAME,',
'      :P7_ITEM_LABEL,',
'      :P7_ITEM_TYPE,',
'      :P7_VALIDATION_TYPE,',
'      :P7_VALIDATION_PARAM,',
'      :P7_LOV_QUERY,',
'      TO_NUMBER(:P7_DISPLAY_ORDER),',
'      :P7_ITEM_CLASS,',
'      :P7_ITEM_CUSTOM_ATTRIBUTE,',
'      v_other_attributes',
'    );',
'  END IF;',
'',
'  COMMIT;',
'',
'  -- Return success message',
'  apex_json.open_object;',
'  apex_json.write(''status'', ''success'');',
'  apex_json.write(''message'', ''Record saved successfully'');',
'  apex_json.close_object;',
'',
'EXCEPTION',
'  WHEN DUP_VAL_ON_INDEX THEN',
'    apex_json.open_object;',
'    apex_json.write(''status'', ''error'');',
'    apex_json.write(''message'', ''Duplicate Field Found.'');',
'    apex_json.close_object;',
'  WHEN OTHERS THEN',
'    apex_json.open_object;',
'    apex_json.write(''status'', ''error'');',
'    apex_json.write(''message'', SQLERRM);',
'    apex_json.close_object;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>49131294292133143645
);
end;
