,p_function_body_language=>'PLSQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_columns VARCHAR2(32767);',
'  vFinalSql VARCHAR2(32767);',
'  v_sql     VARCHAR2(32767);',
'BEGIN',
'  -- Build JSON_VALUE projection for dynamic JSON keys',
'  SELECT LISTAGG(',
'           ''JSON_VALUE(OTHERS_INFO, ''''$.'' || ITEM_NAME || '''''') AS "'' || ITEM_LABEL || ''"'',',
'           '', ''',
'         ) WITHIN GROUP (ORDER BY DISPLAY_ORDER)',
'  INTO v_columns',
'  FROM FORM_METADATA',
'  WHERE FORM_ID = 9;',
'',
'  -- Build the final SQL query',
'  vFinalSql := ''SELECT NULL AS LINK,CUST_ID AS Customer_code, FIRST_NAME, LAST_NAME, '' ||',
'               NVL(v_columns, ''''''NONE'''' AS PLACEHOLDER'') ||',
'               '' FROM MB_CUSTOMER_CHECK '' ;',
'',
'  v_sql := ''SELECT * FROM ('' || vFinalSql || '')'';',
'',
'  RETURN v_sql;',
'END;',
''))
