wwv_flow_imp_page.create_page(
 p_id=>10
,p_name=>'Cash Deposit With OTP'
,p_alias=>'CASH-DEPOSIT-WITH-OTP'
,p_step_title=>'Cash Deposit With OTP'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function fetchAccountInfo(accountNo) {',
'  apex.message.clearErrors("P10_ACCOUNT_NO");',
'  apex.util.showSpinner();',
'  var vPopup = apex.widget.waitPopup();',
'  //apex.widget.waitPopup();',
'',
'  apex.server.process(',
'    "GET_ACCOUNT_INFO",',
'    {',
'      pageItems: "#P10_ACCOUNT_NO"',
'    },',
'    {',
'      dataType: "json",',
'      success: function (pData) {',
'        $(".u-Processing").remove();',
'        vPopup.remove();',
'        ',
'',
'        if (!pData || !pData.account_type) {',
'          ["P10_ACCOUNT_TYPE", "P10_ACCOUNT_TITLE", "P10_MOBILE_NO", "P10_DEPOSIT_AMT", "P10_BEARER_NAME", "P10_BEARER_MOBILE_NO"]',
'            .forEach(item => apex.item(item).setValue(""));',
'',
'          apex.message.alert("No account found with the entered Account Number.", function () {}, {',
'            title: "Account Not Found",',
'            style: "information",',
'            iconClasses: "fa fa-info fa-2x",',
'            okLabel: "Exit and Retry"',
'          });',
'          return;',
'        }',
'',
'        apex.item("P10_ACCOUNT_TYPE").setValue(pData.account_type);',
'        apex.item("P10_ACCOUNT_TITLE").setValue(pData.account_title);',
'        apex.item("P10_MOBILE_NO").setValue(pData.mobile_no);',
'        apex.item("P10_DEPOSIT_AMT").setValue(pData.deposit_amt);',
'        apex.item("P10_BEARER_NAME").setValue(pData.bearer_name);',
'        apex.item("P10_BEARER_MOBILE_NO").setValue(pData.bearer_mobile_no);',
'      },',
'      error: function (jqXHR, textStatus, errorThrown) {',
'        apex.util.hideSpinner();',
'        let msg = "Unable to fetch account information. Please try again.";',
'        if (errorThrown) msg += " (" + errorThrown + ")";',
'        apex.message.alert(msg, function () {}, {',
'          title: "Error",',
'          style: "error",',
'          iconClasses: "fa fa-exclamation-triangle fa-2x",',
'          okLabel: "OK"',
'        });',
'      }',
'    }',
'  );',
'}',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.is-bold {',
'  font-size: medium;',
'  font-weight: 500;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'23'
);
