wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(80285979146481489804)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_ACCOUNT_INFO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_account_no VARCHAR2(20) := :P10_ACCOUNT_NO;',
'BEGIN',
'    IF l_account_no = ''123456'' THEN',
'        apex_json.open_object;',
'        apex_json.write(''account_type'', ''Savings'');',
'        apex_json.write(''account_title'', ''John Doe'');',
'        apex_json.write(''mobile_no'', ''01711111111'');',
'        apex_json.write(''deposit_amt'', 5000);',
'        apex_json.write(''bearer_name'', ''Jane Doe'');',
'        apex_json.write(''bearer_mobile_no'', ''01811111111'');',
'        apex_json.close_object;',
'    ELSIF l_account_no = ''654321'' THEN',
'        apex_json.open_object;',
'        apex_json.write(''account_type'', ''Current'');',
'        apex_json.write(''account_title'', ''Alice Smith'');',
'        apex_json.write(''mobile_no'', ''01722222222'');',
'        apex_json.write(''deposit_amt'', 10000);',
'        apex_json.write(''bearer_name'', ''Bob Smith'');',
'        apex_json.write(''bearer_mobile_no'', ''01822222222'');',
'        apex_json.close_object;',
'    ELSE',
'        -- No match, clear fields',
'        apex_json.open_object;',
'        apex_json.write(''account_type'', '''');',
'        apex_json.write(''account_title'', '''');',
'        apex_json.write(''mobile_no'', '''');',
'        apex_json.write(''deposit_person'', '''');',
'        apex_json.write(''deposit_amt'', '''');',
'        apex_json.write(''bearer_name'', '''');',
'        apex_json.write(''bearer_mobile_no'', '''');',
'        apex_json.close_object;',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>80285979146481489804
);
end;
