prompt --application/pages/page_00011
begin
wwv_flow_imp_page.create_page(
 p_id=>11
,p_name=>'Dynamic Page'
,p_alias=>'DYNAMIC-PAGE1'
,p_step_title=>'Dynamic Page'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function updateJsonData() {',
'  var formData = {};',
'',
'  // Loop through all input fields, selects, and textareas within the form',
'  $("#my_dynamic_form").find("input[name], select[name], textarea[name]").each(function() {',
'    var fieldName = $(this).attr("name");',
'    var fieldValue;',
'',
'    // Handle checkbox inputs (value if checked, null if unchecked)',
'    if ($(this).attr("type") === "checkbox") {',
'      fieldValue = this.checked ? $(this).val() || "Y" : null;  // Default value for checked checkbox is "Y"',
'    }',
'    // Handle radio buttons (only include value of selected radio button)',
'    else if ($(this).attr("type") === "radio") {',
'      if (this.checked) {',
'        fieldValue = $(this).val();',
'      } else {',
'        return; // Skip unchecked radio buttons',
'      }',
'    }',
'    // For all other input types (text, select, textarea)',
'    else {',
'      fieldValue = $(this).val();',
'    }',
'',
'    // Only add non-null values to the JSON object',
'    if (fieldName && fieldValue !== undefined && fieldValue !== null) {',
'      formData[fieldName] = fieldValue;',
'    }',
'  });',
'',
'  // Convert the form data into a JSON string',
'  var jsonData = JSON.stringify(formData);',
'',
'  // Set the JSON string to the APEX item (e.g., :P6_JSON_DATA)',
'  $("#P6_JSON_DATA").val(jsonData); // assuming P6_JSON_DATA is the hidden item to store the JSON',
'}',
'',
'// Bind the updateJsonData function to the change, keyup, and click events (delegated)',
'$("#my_dynamic_form").on("change keyup click", "input[name], select[name], textarea[name]", updateJsonData);',
'',
'',
'',
'function validateNumber(event, item, maxLength) {',
'  maxLength = maxLength || 14;',
'',
'  // Keys allowed even if not digit',
'  const controlKeys = [''Backspace'', ''Delete'', ''ArrowLeft'', ''ArrowRight'', ''Tab'', ''Home'', ''End''];',
'',
'  // Allow control keys always',
'  if (controlKeys.includes(event.key)) {',
'    // Clear any custom validity on these keys',
'    item.setCustomValidity('''');',
'    return;',
'  }',
'',
'  // Allow digits and one dot',
'  if ((event.key >= ''0'' && event.key <= ''9'') || event.key === ''.'') {',
'    // Prevent more than one dot',
'    if (event.key === ''.'' && item.value.includes(''.'')) {',
'      event.preventDefault();',
'      return;',
'    }',
'',
'    // Check length of digits only (exclude dot)',
'    let currentVal = item.value.replace(/\./g, '''');',
'    // If selection is active, account for that because new char replaces selection',
'    let selectionLength = item.selectionEnd - item.selectionStart;',
'',
'    // New length after this key press',
'    let newLength = currentVal.length - selectionLength + 1;',
'',
'    if (newLength > maxLength) {',
'      event.preventDefault();',
'      var errorMsg = `Only ${maxLength} digits are allowed, Length found: ${newLength}`;',
'      item.setCustomValidity(errorMsg);',
'      item.reportValidity();',
'      return;',
'    }',
'',
'    // Clear any previous errors',
'    item.setCustomValidity('''');',
'  } else {',
'    // Block any other keys',
'    event.preventDefault();',
'    var errorMsg = "Please enter a valid number.";',
'    item.setCustomValidity(errorMsg);',
'    item.reportValidity();',
'  }',
'}',
'',
'',
'function submitDynamicForm() {',
'  var formData = {};',
'',
'  $("#my_dynamic_form input, #my_dynamic_form select").each(function() {',
'    formData[$(this).attr("name")] = $(this).val();',
'  });',
'',
'  apex.server.process("SAVE_DYNAMIC_FORM",',
'    {',
'      pageItems: ''#P6_FORM_NAME'',',
'      x01: JSON.stringify(formData)',
'    },',
'    {',
'      dataType: "json",  // Tell it to expect JSON response',
'      success: function(pData) {',
'        if(pData.status === "success"){',
'          apex.message.showPageSuccess(pData.message);',
'        } else {',
'          apex.message.alert("Error: " + pData.message);',
'        }',
'      },',
'      error: function(request, status, error) {',
'        apex.message.alert("Error submitting form: " + error);',
'        console.log(error);',
'      }',
'    }',
'  );',
'}',
''))
,p_step_template=>2526643373347724467
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(97204087358587564914)
,p_plug_name=>'Dynamic Form Region'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="t-Form-itemWrapper">',
'  <div id="my_dynamic_form">',
'',
'    <!-- Row 1 -->',
'    <div class="t-Form-fieldContainer apex-item-wrapper apex-item-wrapper--text-field t-Form-fieldContainer--large">',
'      <div class="t-Form-labelContainer col col-2">',
'        <label for="FATHER_NAME" class="t-Form-label">FATHER NAME</label>',
'      </div>',
'      <div class="t-Form-inputContainer col col-4">',
'        <div class="t-Form-itemWrapper">',
'          <input type="text" id="FATHER_NAME" name="FATHER_NAME" class="text_field apex-item-text" maxlength="11" />',
'        </div>',
'        <div class="t-Form-itemAssistance"></div>',
'      </div>',
'    </div>',
'',
'    <div class="t-Form-fieldContainer is-required apex-item-wrapper apex-item-wrapper--text-field">',
'      <div class="t-Form-labelContainer col col-2">',
'        <label for="MOBILE_NUMBER" class="t-Form-label">MOBILE NUMBER</label>',
'      </div>',
'      <div class="t-Form-inputContainer col col-4">',
'        <div class="t-Form-itemWrapper">',
'          <input type="text" id="MOBILE_NUMBER" name="MOBILE_NUMBER"',
'            class="text_field apex-item-text"',
'            onkeydown="validateNumber(event, this, 11)"',
'            oninput="if(this.value.length > 11) this.value=this.value.slice(0,11)" />',
'        </div>',
'        <div class="t-Form-itemAssistance">',
'          <div class="t-Form-itemRequired" aria-hidden="true">Required</div>',
'        </div>',
