,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Global variable to hold current audio',
'var currentAudio = null;',
'',
'function playNotificationSound() {',
'    // Stop previous sound if already playing',
'    if (currentAudio && !currentAudio.paused) {',
'        currentAudio.pause();',
'        currentAudio.currentTime = 0;',
'    }',
'',
'    // Create new Audio object and store it globally',
'    currentAudio = new Audio(''#APP_FILES#alert.mp3''); ',
'    currentAudio.play().catch(function (err) {',
'        console.warn(''Audio play blocked:'', err);',
'    });',
'}',
'',
'function stopNotificationSound() {',
'    if (currentAudio && !currentAudio.paused) {',
'        currentAudio.pause();',
'        currentAudio.currentTime = 0;',
'    }',
'}',
'',
'',
'// Global speech synthesis variables',
'var synth = window.speechSynthesis;',
'var currentUtterance = null;',
'',
'// Function to speak static Bangla text',
'function speakBangla() {',
unistr('    var text = "\0986\09AA\09A8\09BE\09B0 \09A1\09C7\099F\09BE \09B8\09AB\09B2\09AD\09BE\09AC\09C7 \099C\09AE\09BE \09B9\09AF\09BC\09C7\099B\09C7"; // Your static Bangla message'),
'',
'    // Stop any existing speech',
'    if (synth.speaking) {',
'        synth.cancel();',
'    }',
'',
'    currentUtterance = new SpeechSynthesisUtterance(text);',
'',
'    // Optional settings',
'    currentUtterance.pitch = 1;',
'    currentUtterance.rate = 1;',
'    currentUtterance.volume = 1;',
'',
'    // Choose a Bengali voice if available',
'    var voices = synth.getVoices();',
'    var bnVoice = voices.find(v => v.lang.startsWith(''bn'')); // bn-BD or bn-IN',
'    if (bnVoice) {',
'        currentUtterance.voice = bnVoice;',
'    }',
'',
'    synth.speak(currentUtterance);',
'}',
'',
'// Function to stop speech',
'function stopBangla() {',
'    if (synth.speaking) {',
'        synth.cancel();',
'    }',
'}',
'',
'// Optional: log available voices',
'synth.onvoiceschanged = function() {',
'    console.log(''Available voices:'', synth.getVoices());',
'};',
''))
