'.ck-counter-container {',
'    display: flex;',
'    align-items: center;',
'    gap: 10px;',
'    margin-top: 6px;',
'    font-size: 12px;',
'}',
'',
'.ck-word-pill {',
'    background: #eef2ff;',
'    color: #4338ca;',
'    padding: 3px 10px;',
'    border-radius: 999px;',
'    font-weight: 600;',
'}',
'',
'.ck-progress {',
'    flex: 1;',
'    height: 6px;',
'    background: #e5e7eb;',
'    border-radius: 6px;',
'    overflow: hidden;',
'}',
'',
'.ck-progress-bar {',
'    height: 100%;',
'    width: 0%;',
'    background: linear-gradient(90deg, #6366f1, #4f46e5);',
'    transition: width 0.2s ease;',
'}',
'',
'.ck-char-count {',
'    font-weight: 600;',
'}',
'',
'.ck-counter-container.limit-reached .ck-progress-bar {',
'    background: #dc2626;',
'}',
'',
'.ck-counter-container.shake {',
'    animation: shake 0.25s;',
'}',
'',
'@keyframes shake {',
'    0% { transform: translateX(0); }',
'    25% { transform: translateX(-2px); }',
'    50% { transform: translateX(2px); }',
'    75% { transform: translateX(-2px); }',
'    100% { transform: translateX(0); }',
'}',
'',
'.ck-toolbar {',
'    border-radius: 6px;',
'}',
'',
'.ck-toolbar__items {',
'    gap: 4px;',
'}',
'',
'.ck-tooltip {',
'    font-size: 12px;',
'}',
''))
