,p_name=>'P15_RICH_TEXT_EDITOR'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(121063403245935173717)
,p_display_as=>'NATIVE_RICH_TEXT_EDITOR'
,p_grid_label_column_span=>0
,p_field_template=>2040785906935475274
,p_item_template_options=>'#DEFAULT#'
,p_plugin_init_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function (options) {',
'    options.editorOptions.removePlugins = options.editorOptions.removePlugins || [];',
'    options.editorOptions.removePlugins.push("Autoformat");',
'',
'    /*options.editorOptions.toolbar = [',
'        "heading",',
'        "bulletedList",',
'        "numberedList",',
'        "|",',
'        "fontSize",',
'        "undo",',
'        "redo"',
'    ];*/',
'',
'    const MAX_LIMIT = 400;',
'',
'    setTimeout(() => {',
'        const editorMain = document.querySelector(".ck-editor__main");',
'        if (!editorMain || document.querySelector(".ck-counter-container")) return;',
'        editorMain.insertAdjacentHTML(',
'            "afterend",',
'            `<div class="ck-counter-container">',
'                <span class="ck-word-pill">0 words</span>',
'                <div class="ck-progress"><div class="ck-progress-bar"></div></div>',
'                <span class="ck-char-count">0 / ${MAX_LIMIT}</span>',
'            </div>`',
'        );',
'',
'        const container = editorMain.nextElementSibling;',
'        const wordPill = container.querySelector(".ck-word-pill");',
'        const bar = container.querySelector(".ck-progress-bar");',
'        const charCount = container.querySelector(".ck-char-count");',
'        const editable = editorMain.querySelector(".ck-content");',
'',
'        if (!editable) return;',
'        const getText = () =>',
'            editable.innerText.replace(/\n/g, "");',
'',
'        const setText = (text) => {',
'            editable.innerText = text;',
'            placeCaretAtEnd(editable);',
'        };',
'',
'        const placeCaretAtEnd = (el) => {',
'            const range = document.createRange();',
'            const sel = window.getSelection();',
'            range.selectNodeContents(el);',
'            range.collapse(false);',
'            sel.removeAllRanges();',
'            sel.addRange(range);',
'        };',
'',
'        const updateUI = () => {',
'            const text = getText();',
'            const len = text.length;',
'            const words = text.trim() ? text.trim().split(/\s+/).length : 0;',
'            const pct = Math.min((len / MAX_LIMIT) * 100, 100);',
'',
'            wordPill.textContent = `${words} words`;',
'            charCount.textContent = `${len} / ${MAX_LIMIT}`;',
'            bar.style.width = pct + "%";',
'',
'            container.classList.toggle("limit-reached", len >= MAX_LIMIT);',
'        };',
'        editable.addEventListener("keydown", (e) => {',
'            const len = getText().length;',
'            const allowedKeys = [',
'                "Backspace",',
'                "Delete",',
'                "ArrowLeft",',
'                "ArrowRight",',
'                "ArrowUp",',
'                "ArrowDown",',
'                "Tab"',
'            ];',
'',
'            if (allowedKeys.includes(e.key) || e.ctrlKey || e.metaKey) return;',
'',
'            if (len >= MAX_LIMIT) {',
'                e.preventDefault();',
'                container.classList.add("shake");',
'                setTimeout(() => container.classList.remove("shake"), 250);',
'            }',
'        });',
'        editable.addEventListener("paste", (e) => {',
'            e.preventDefault();',
'',
'            const text = getText();',
'            const space = MAX_LIMIT - text.length;',
'            if (space <= 0) return;',
'',
'            const paste = e.clipboardData.getData("text").substring(0, space);',
'            document.execCommand("insertText", false, paste);',
'        });',
'        editable.addEventListener("drop", (e) => e.preventDefault());',
'        const observer = new MutationObserver(() => {',
'            const text = getText();',
'            if (text.length > MAX_LIMIT) {',
'                setText(text.substring(0, MAX_LIMIT));',
'            }',
'            updateUI();',
'        });',
'',
'        observer.observe(editable, {',
'            childList: true,',
'            characterData: true,',
'            subtree: true',
'        });',
'',
'        updateUI();',
'    }, 400);',
'',
'    return options;',
'}',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'allow_custom_html', 'Y',
  'format', 'HTML',
  'min_height', '180',
  'toolbar', 'INTERMEDIATE',
  'toolbar_style', 'OVERFLOW')).to_clob
);
end;
